contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        require(amount >= 0);
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 balanceAfter = address(c).balance;
        assert(!reverted && balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

